with customer_summary as (select customer_id, max(started_at) as latest_started_at, sort_array(collect_set(device)) as device_list from sessions group by customer_id) select customers.id, customers.city, customer_summary.latest_started_at, customer_summary.device_list from customers left join customer_summary on customers.id = customer_summary.customer_id order by customers.id, customer_summary.latest_started_at desc;
